tool_calls.arguments:
{"command": "kubectl patch deploy app -n restricted-app --type=strategic -p '{
  "spec": {
    "template": {
      "spec": {
        "securityContext": {
          "runAsNonRoot": true,
          "runAsUser": 1000,
          "seccompProfile": {"type": "RuntimeDefault"}
        },
        "containers": [
          {
            "name": "app",
            "securityContext": {
              "allowPrivilegeEscalation": false,
              "capabilities": {"drop": ["ALL"]}
            }
          }
        ]
      }
    }
  }
}'"}

